import { useNavigate } from 'react-router-dom';
import { Link } from 'react-router-dom';
import { useEffect, useState } from 'react';
import { SidebarHistory } from '@/components/sidebar-history';
import { SidebarUserNav } from '@/components/sidebar-user-nav';
import {
  Sidebar,
  SidebarContent,
  SidebarFooter,
  SidebarHeader,
  SidebarMenu,
  SidebarMenuButton,
  SidebarMenuItem,
  useSidebar,
} from '@/components/ui/sidebar';
import { Tooltip, TooltipContent, TooltipTrigger } from '@/components/ui/tooltip';
import { DbIcon } from '@/components/ui/db-icon';
import { NewChatIcon, SidebarCollapseIcon, SidebarExpandIcon } from '@/components/icons';
import { cn } from '@/lib/utils';
import type { ClientSession } from '@chat-template/auth';
import { Action } from './elements/actions';

const LOGO_DARK = "data:image/png;base64,";
const LOGO_LIGHT = "data:image/png;base64,";

function useThemeMode() {
  const [isDark, setIsDark] = useState(() =>
    document.documentElement.classList.contains('dark')
  );

  useEffect(() => {
    const observer = new MutationObserver(() => {
      setIsDark(document.documentElement.classList.contains('dark'));
    });
    observer.observe(document.documentElement, {
      attributes: true,
      attributeFilter: ['class'],
    });
    return () => observer.disconnect();
  }, []);

  return isDark;
}

export function AppSidebar({
  user,
  preferredUsername,
}: {
  user: ClientSession['user'] | undefined;
  preferredUsername: string | null;
}) {
  const navigate = useNavigate();
  const { setOpenMobile, open, openMobile, isMobile, toggleSidebar } = useSidebar();
  const isDark = useThemeMode();

  const effectiveOpen = open || (isMobile && openMobile);

  return (
    <Sidebar
      collapsible="icon"
      className="group-data-[side=left]:border-r-0"
    >
      {/* Header: Logo + app title + collapse toggle */}
      <SidebarHeader
        className={cn(
          'flex-col items-start gap-0 px-2 py-2',
          !effectiveOpen && 'items-center py-2',
        )}
      >
        {/* Versant Logo */}
        {effectiveOpen && (
          <div className="px-1 mb-2">
            <Link to="/" onClick={() => setOpenMobile(false)}>
              <img
                src={isDark ? LOGO_DARK : LOGO_LIGHT}
                alt="Versant"
                className="h-7 w-auto object-contain"
              />
            </Link>
          </div>
        )}

        {/* Title row + collapse toggle */}
        <div className={cn(
          'flex w-full items-center gap-2',
          effectiveOpen ? 'justify-between' : 'justify-center',
        )}>
          {effectiveOpen && (
            <Link
              to="/"
              onClick={() => setOpenMobile(false)}
              className="flex items-center overflow-hidden px-1"
            >
              <span className="text-base font-semibold text-foreground">
                Press Release Generator
              </span>
            </Link>
          )}

          <Action
            onClick={toggleSidebar}
            tooltip={effectiveOpen ? 'Collapse sidebar' : 'Expand sidebar'}
          >
            <DbIcon
              icon={effectiveOpen ? SidebarCollapseIcon : SidebarExpandIcon}
              size={16}
              color="muted"
            />
          </Action>
        </div>
      </SidebarHeader>

      {/* Nav: New Chat */}
      <div className="px-2 pt-2">
        <SidebarMenu>
          <SidebarMenuItem>
            <Tooltip>
              <TooltipTrigger asChild>
                <SidebarMenuButton
                  type="button"
                  className="h-8 p-1 md:p-2 cursor-pointer"
                  onClick={() => {
                    setOpenMobile(false);
                    navigate('/');
                  }}
                >
                  <DbIcon icon={NewChatIcon} size={16} color="default" />
                  <span className="group-data-[collapsible=icon]:hidden">
                    New chat
                  </span>
                </SidebarMenuButton>
              </TooltipTrigger>
              <TooltipContent side="right" style={{ display: open ? 'none' : 'block' }}>New chat</TooltipContent>
            </Tooltip>
          </SidebarMenuItem>

        </SidebarMenu>
      </div>

      {/* Chat history */}
      <SidebarContent>
        {effectiveOpen && <SidebarHistory user={user} />}
      </SidebarContent>

      {/* User nav */}
      <SidebarFooter>
        {user && (
          <SidebarUserNav user={user} preferredUsername={preferredUsername} />
        )}
      </SidebarFooter>
    </Sidebar>
  );
}
